	let tileWorldOrigin = vec2f(
		f32(cx) * tmx.uCellSize.x,
		(f32(cy) + 1.0) * tmx.uCellSize.y - tmx.uTileSize.y,
	);
	var inTile = (worldPx - tileWorldOrigin) / tmx.uTileSize;
	if (inTile.x < 0.0 || inTile.x >= 1.0 || inTile.y < 0.0 || inTile.y >= 1.0) {
		return miss;
	}

